/* The component's styles are encapsulated in its shadow root. */

otp-input {

  --otp-cell: #232323;

  --otp-text: #dedede;

  --otp-success: #00c988;

  --otp-success-bg: #06251a;

  --otp-error: #ff7777;

  font-family: Arial, Helvetica, sans-serif;

}

const styles = `

  :host { display: block; color: var(--otp-text, #dedede); font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Helvetica, Arial, sans-serif; -webkit-font-smoothing: antialiased; }

  * { box-sizing: border-box; }

  .wrap { position: relative; --merge-inset: 20px; }

  label { display: block; padding-inline: 0; font-size: 17px; font-weight: 400; letter-spacing: -.02em; line-height: 1.4; margin-bottom: 16px; color: var(--otp-text, #dedede); opacity: .65; transition: padding 650ms cubic-bezier(.22,1,.36,1); }

  .joined label { padding-inline: var(--merge-inset); }

  .field { position: relative; }

  .cells { display: flex; gap: 8px; padding: 0; transition: gap 650ms cubic-bezier(.22,1,.36,1), padding 650ms cubic-bezier(.22,1,.36,1); }

  .cell { position: relative; flex: 1; min-width: 0; height: 64px; overflow: hidden; border-radius: 18px; background: var(--otp-cell, #232323); transition: border-radius 650ms cubic-bezier(.22,1,.36,1), background 650ms ease, box-shadow 200ms; }

  .glyph { position: absolute; inset: 0; display: grid; place-items: center; font-family: 'SFMono-Regular', Consolas, 'Liberation Mono', monospace; font-size: 26px; font-weight: 400; line-height: 1; }

  .caret { position: absolute; left: calc(50% - 1px); top: 27%; height: 46%; width: 2px; background: var(--otp-text, #dedede); animation: blink 1.1s step-end infinite; }

  input { position: absolute; inset: 0; width: 100%; height: 100%; opacity: 0; border: 0; padding: 0; font-size: 20px; cursor: text; }

  .field:has(input:focus-visible) .cell.active { box-shadow: inset 0 0 0 1px var(--otp-focus, #ffffff30); }

  .joined .cells { gap: 0; padding: 0 var(--merge-inset); }

  .joined .cell { border-radius: 0; }

  .joined .cell:first-child { border-radius: 18px 0 0 18px; }

  .joined .cell:last-child { border-radius: 0 18px 18px 0; }

  .success .cell { background: var(--otp-success-bg, #06251a); color: var(--otp-success, #00c988); }

  .error .cell { background: var(--otp-error-bg, #2d1416); color: var(--otp-error, #ff7777); }

  .actions { position: absolute; top: calc(100% + 12px); width: 100%; display: flex; justify-content: center; }

  button { font: inherit; font-size: 12px; font-weight: 400; line-height: 1.5; letter-spacing: .01em; color: var(--otp-text, #dedede); opacity: .4; background: none; border: 0; min-height: 44px; padding: 10px 16px; cursor: pointer; border-radius: 8px; animation: action-appear 400ms both; transition: opacity 180ms ease; }

  button:hover { opacity: .75; }

  button:focus-visible { opacity: 1; outline: 1px solid currentColor; outline-offset: 3px; }

  .sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }

  @keyframes blink { 50% { opacity: 0; } }

  @keyframes action-appear { from { transform: translateY(4px); filter: blur(2px); } to { transform: none; filter: blur(0); } }

  @media (max-width: 360px) { .cells { gap: 6px; } .cell { height: 58px; } .glyph { font-size: 24px; } }

  @media (prefers-reduced-motion: reduce) { *, *::before, *::after { transition-duration: .01ms !important; animation-duration: .01ms !important; animation-iteration-count: 1 !important; } }

`;


/** Six-digit OTP with an asynchronous verification hook and animated result. */

class OTPInput extends HTMLElement {

  constructor() {

    super();

    this.attachShadow({ mode: 'open' });

    this.state = 'idle';

    this.previous = '';

    this.run = 0;

    this.motion = matchMedia('(prefers-reduced-motion: reduce)');

  }


  connectedCallback() {

    if (this.input) return;

    this.shadowRoot.innerHTML = `<style>${styles}</style>

      <div class="wrap">

        <label for="code"></label>

        <div class="field">

          <div class="cells" aria-hidden="true">${Array.from({ length: 6 }, () => '<div class="cell"><span class="glyph"></span></div>').join('')}</div>

          <input id="code" type="text" inputmode="numeric" autocomplete="one-time-code" spellcheck="false" aria-describedby="hint" />

        </div>

        <span id="hint" class="sr">Enter your six-digit verification code. Verification starts automatically.</span>

        <span class="sr" role="status" aria-live="polite"></span>

        <div class="actions"></div>

      </div>`;

    this.shadowRoot.querySelector('label').textContent = this.getAttribute('label') || 'Verification Code';

    this.wrap = this.shadowRoot.querySelector('.wrap');

    this.input = this.shadowRoot.querySelector('input');

    this.cells = [...this.shadowRoot.querySelectorAll('.cell')];

    this.status = this.shadowRoot.querySelector('[role=status]');

    this.actions = this.shadowRoot.querySelector('.actions');

    this.input.addEventListener('input', () => this.onInput());

    for (const event of ['focus', 'blur', 'keyup', 'select', 'click']) {

      this.input.addEventListener(event, () => this.render());

    }

    this.input.addEventListener('pointerdown', (event) => {

      if (this.state !== 'idle') return;

      const bounds = this.input.getBoundingClientRect();

      const index = Math.min(this.input.value.length, Math.max(0, Math.floor((event.clientX - bounds.left) / (bounds.width / 6))));

      event.preventDefault();

      this.input.focus();

      this.input.setSelectionRange(index, Math.min(index + 1, this.input.value.length));

      this.render();

    });

    this.render();

  }


  disconnectedCallback() {

    this.run++;

    this.controller?.abort();

    clearInterval(this.shuffle);

  }


  get value() { return this.input?.value || ''; }


  onInput() {

    const position = this.input.selectionStart;

    const raw = this.input.value;

    this.input.value = raw.replace(/[^0-9]/g, '').slice(0, 6);

    const cleanPosition = raw.slice(0, position).replace(/[^0-9]/g, '').length;

    this.input.setSelectionRange(cleanPosition, cleanPosition);

    this.render();

    this.dispatchEvent(new CustomEvent('otp-change', { detail: { value: this.value }, bubbles: true, composed: true }));

    if (this.value.length === 6) this.submit();

  }


  paint(index, character, animate = true) {

    const cell = this.cells[index];

    const current = cell.querySelector('.glyph');

    if (current.textContent === character) return;

    if (!animate || this.motion.matches) { current.textContent = character; return; }

    const outgoing = current.cloneNode(true);

    outgoing.className = 'outgoing glyph';

    cell.append(outgoing);

    outgoing.animate([

      { transform: 'translateY(0)', opacity: .6, filter: 'blur(0px)' },

      { transform: 'translateY(-28px)', opacity: 0, filter: 'blur(5px)' }

    ], { duration: 190, easing: 'ease-out' }).finished.then(() => outgoing.remove()).catch(() => outgoing.remove());

    current.textContent = character;

    current.getAnimations().forEach(animation => animation.cancel());

    current.animate([

      { transform: 'translateY(22px)', opacity: .2, filter: 'blur(5px)' },

      { transform: 'translateY(0)', opacity: 1, filter: 'blur(0px)' }

    ], { duration: 240, easing: 'cubic-bezier(.16,1,.3,1)' });

  }


  render() {

    if (this.state !== 'idle') return;

    const focused = this.shadowRoot.activeElement === this.input;

    const active = Math.min(this.input.selectionStart ?? this.value.length, 5);

    this.cells.forEach((cell, index) => {

      this.paint(index, this.value[index] || '');

      cell.classList.toggle('active', focused && index === active);

      cell.querySelector('.caret')?.remove();

      if (focused && index === active && !this.value[index]) {

        const caret = document.createElement('span');

        caret.className = 'caret';

        cell.append(caret);

      }

    });

  }


  async submit() {

    if (this.state !== 'idle') return;

    const code = this.value;

    const token = ++this.run;

    this.controller = new AbortController();

    this.state = 'verifying';

    this.input.readOnly = true;

    this.input.setAttribute('aria-busy', 'true');

    this.cells.forEach(cell => { cell.classList.remove('active'); cell.querySelector('.caret')?.remove(); });

    this.wrap.className = 'wrap joined';

    this.status.textContent = 'Verifying code.';

    const alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789$%&';

    let tick = 0;

    const scramble = () => this.cells.forEach((_, index) => this.paint(index, alphabet[(tick * 7 + index * 11 + Math.floor(Math.random() * 9)) % alphabet.length]));

    if (!this.motion.matches) this.shuffle = setInterval(() => { tick++; scramble(); }, 110);

    let passed = false;

    try {

      if (typeof this.verify !== 'function') throw new Error('A verify callback is required.');

      const [result] = await Promise.all([

        this.verify(code, { signal: this.controller.signal }),

        new Promise(resolve => setTimeout(resolve, this.motion.matches ? 0 : 1000))

      ]);

      passed = result === true;

    } catch (error) {

      if (token !== this.run) return;

      this.dispatchEvent(new CustomEvent('otp-error', { detail: { error }, bubbles: true, composed: true }));

    }

    if (token !== this.run) return;

    clearInterval(this.shuffle);

    this.wrap.classList.add(passed ? 'success' : 'error');

    const word = passed ? 'PASSED' : 'RETRY!';

    for (let index = 0; index < 6; index++) {

      if (token !== this.run) return;

      this.paint(index, word[index]);

      if (!this.motion.matches) {

        for (let step = 0; step < 2; step++) {

          await new Promise(resolve => setTimeout(resolve, 65));

          if (token !== this.run) return;

          for (let next = index + 1; next < 6; next++) this.paint(next, alphabet[Math.floor(Math.random() * alphabet.length)]);

        }

      }

    }

    this.state = passed ? 'success' : 'error';

    this.input.removeAttribute('aria-busy');

    this.input.setAttribute('aria-invalid', String(!passed));

    this.status.textContent = passed ? 'Code verified successfully.' : 'Verification failed. Please try again.';

    const button = document.createElement('button');

    button.type = 'button';

    button.textContent = passed ? 'Try again' : 'Retry verification';

    button.addEventListener('click', () => this.reset());

    this.actions.replaceChildren(button);

    this.dispatchEvent(new CustomEvent('otp-complete', { detail: { passed }, bubbles: true, composed: true }));

  }


  reset({ focus = true } = {}) {

    this.run++;

    this.controller?.abort();

    clearInterval(this.shuffle);

    this.state = 'idle';

    this.input.value = '';

    this.input.readOnly = false;

    this.input.removeAttribute('aria-busy');

    this.input.removeAttribute('aria-invalid');

    this.wrap.className = 'wrap';

    this.actions.replaceChildren();

    this.status.textContent = 'Enter a new verification code.';

    if (focus) this.input.focus();

    this.render();

  }

}


if (!customElements.get('otp-input')) customElements.define('otp-input', OTPInput);
